import {
  forwardRef,
  useId,
  useInsertionEffect,
  type CSSProperties,
  type HTMLAttributes,
} from "react";

export type NeatAnnotationDirection = "n" | "ne" | "e" | "se" | "s" | "sw" | "w" | "nw";

export type NeatAnnotationTone =
  | "neutral"
  | "amber"
  | "blue"
  | "green"
  | "red"
  | "purple"
  | "rainbow";

export interface NeatAnnotationStyle extends CSSProperties {
  "--bui-annotation-color"?: string;
  "--bui-annotation-mark"?: string;
  "--bui-annotation-font"?: string;
  "--bui-annotation-font-size"?: string;
  "--bui-annotation-target-gap"?: string;
  "--bui-annotation-label-gap"?: string;
  "--bui-annotation-lower-label-gap"?: string;
  "--bui-annotation-label-max-width"?: string;
  "--bui-annotation-arrow-x"?: string;
  "--bui-annotation-arrow-y"?: string;
  "--bui-annotation-text-x"?: string;
  "--bui-annotation-text-y"?: string;
  "--bui-annotation-rotate"?: string;
}

export interface NeatAnnotationProps extends Omit<
  HTMLAttributes<HTMLSpanElement>,
  "color" | "style"
> {
  /** Handwritten note placed beside the target. Omit it for a highlight-only annotation. */
  note?: string;
  /** Compass direction the arrow points toward the target. */
  direction?: NeatAnnotationDirection;
  /** Built-in color treatment for the marker, arrow, and note. */
  tone?: NeatAnnotationTone;
  /** Any CSS color. Overrides the built-in tone color. */
  color?: string;
  /** Whether to tint the target behind its content. */
  highlight?: boolean;
  /** Hides the note from assistive technology when it is purely decorative. */
  decorative?: boolean;
  /** Native styles plus typed annotation tuning variables. */
  style?: NeatAnnotationStyle;
}

const STYLE_ID = "boring-ui-neat-annotation-styles";

const STYLE_TEXT = `
.bui-neat-annotation {
  --bui-annotation-color: oklch(0.62 0.005 30);
  --bui-annotation-mark: color-mix(in oklch, var(--bui-annotation-color) 15%, transparent);
  --bui-annotation-font: "Shantell Sans", "Comic Sans MS", "Bradley Hand", cursive;
  --bui-annotation-font-size: 0.95rem;
  --bui-annotation-target-gap: 5px;
  --bui-annotation-label-gap: 6px;
  --bui-annotation-lower-label-gap: -4px;
  --bui-annotation-label-max-width: 150px;
  --bui-annotation-arrow-x: 0px;
  --bui-annotation-arrow-y: 0px;
  --bui-annotation-text-x: 0px;
  --bui-annotation-text-y: 5px;
  --bui-annotation-rotate: -4deg;
  position: relative;
  display: inline-block;
  overflow: visible;
  line-height: 1.15;
  border-radius: 3px;
  background: var(--bui-annotation-mark);
  box-shadow:
    -0.3em 0 0 0 var(--bui-annotation-mark),
    0.3em 0 0 0 var(--bui-annotation-mark);
}

.bui-neat-annotation[data-highlight="false"] {
  --bui-annotation-mark: transparent;
}

.bui-neat-annotation[data-tone="amber"] {
  --bui-annotation-color: #b8751a;
}

.bui-neat-annotation[data-tone="blue"] {
  --bui-annotation-color: #3b72c4;
}

.bui-neat-annotation[data-tone="green"] {
  --bui-annotation-color: #2f8f5b;
}

.bui-neat-annotation[data-tone="red"] {
  --bui-annotation-color: #c45a38;
}

.bui-neat-annotation[data-tone="purple"] {
  --bui-annotation-color: #8657c8;
}

.bui-neat-annotation[data-tone="rainbow"] {
  --bui-annotation-color: oklch(0.65 0.28 var(--bui-annotation-rainbow-hue, 350deg));
}

.bui-neat-annotation__arrow,
.bui-neat-annotation__label {
  position: absolute;
  pointer-events: none;
  user-select: none;
}

.bui-neat-annotation__arrow {
  z-index: 3;
  width: 46px;
  height: 38px;
  transform-origin: 50% 50%;
  -webkit-mask: var(--bui-annotation-arrow-mask) center / contain no-repeat;
  mask: var(--bui-annotation-arrow-mask) center / contain no-repeat;
  background: var(--bui-annotation-color);
  opacity: 0.9;
}

.bui-neat-annotation__label {
  z-index: 4;
  width: max-content;
  max-width: var(--bui-annotation-label-max-width);
  font-family: var(--bui-annotation-font);
  font-size: var(--bui-annotation-font-size);
  font-weight: 400;
  line-height: 1.05;
  color: var(--bui-annotation-color);
  opacity: 0.9;
  white-space: normal;
  overflow-wrap: anywhere;
}

.bui-neat-annotation__description {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

.bui-neat-annotation[data-direction="n"] > .bui-neat-annotation__arrow {
  left: calc(50% - 23px + var(--bui-annotation-arrow-x));
  top: calc(100% + var(--bui-annotation-target-gap) - 4px + var(--bui-annotation-arrow-y));
  --bui-annotation-arrow-mask: url("data:image/svg+xml,%3Csvg width='46' height='38' viewBox='0 0 46 38' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M23 35 C22 26 22 15 23 4' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round'/%3E%3Cpath d='M17 10 L23 3 L29 10' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
}

.bui-neat-annotation[data-direction="n"] > .bui-neat-annotation__label {
  left: calc(50% + var(--bui-annotation-text-x));
  top: calc(100% + var(--bui-annotation-target-gap) + 31px + var(--bui-annotation-lower-label-gap) + var(--bui-annotation-text-y));
  transform: translateX(-50%) rotate(var(--bui-annotation-rotate));
}

.bui-neat-annotation[data-direction="ne"] > .bui-neat-annotation__arrow {
  left: calc(50% - 40px + var(--bui-annotation-arrow-x));
  top: calc(100% + var(--bui-annotation-target-gap) - 6px + var(--bui-annotation-arrow-y));
  transform: translateX(-10%);
  --bui-annotation-arrow-mask: url("data:image/svg+xml,%3Csvg width='46' height='38' viewBox='0 0 46 38' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M6 32 C16 30 28 18 40 6' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round'/%3E%3Cpath d='M30 10 L40 6 L36 16' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
}

.bui-neat-annotation[data-direction="ne"] > .bui-neat-annotation__label {
  left: calc(50% - 34px + var(--bui-annotation-text-x));
  top: calc(100% + var(--bui-annotation-target-gap) + 26px + var(--bui-annotation-lower-label-gap) + var(--bui-annotation-text-y));
  transform: translateX(-60%) rotate(var(--bui-annotation-rotate));
}

.bui-neat-annotation[data-direction="e"] > .bui-neat-annotation__arrow {
  left: calc(-1 * var(--bui-annotation-target-gap) - 43px + var(--bui-annotation-arrow-x));
  top: calc(50% - 19px + var(--bui-annotation-arrow-y));
  --bui-annotation-arrow-mask: url("data:image/svg+xml,%3Csvg width='46' height='38' viewBox='0 0 46 38' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M4 19 C15 18 31 18 43 19' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round'/%3E%3Cpath d='M36 13 L43 19 L36 25' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
}

.bui-neat-annotation[data-direction="e"] > .bui-neat-annotation__label {
  right: calc(100% + var(--bui-annotation-target-gap) + 39px + var(--bui-annotation-label-gap) - var(--bui-annotation-text-x));
  top: calc(50% - 5px + var(--bui-annotation-text-y));
  transform: translateY(-50%) rotate(var(--bui-annotation-rotate));
}

.bui-neat-annotation[data-direction="se"] > .bui-neat-annotation__arrow {
  left: calc(50% - 40px + var(--bui-annotation-arrow-x));
  top: calc(-1 * var(--bui-annotation-target-gap) - 32px + var(--bui-annotation-arrow-y));
  transform: translateX(-10%);
  --bui-annotation-arrow-mask: url("data:image/svg+xml,%3Csvg width='46' height='38' viewBox='0 0 46 38' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M6 6 C16 8 28 20 40 32' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round'/%3E%3Cpath d='M36 22 L40 32 L30 28' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
}

.bui-neat-annotation[data-direction="se"] > .bui-neat-annotation__label {
  left: calc(50% - 34px + var(--bui-annotation-text-x));
  bottom: calc(100% + var(--bui-annotation-target-gap) + 26px + var(--bui-annotation-label-gap) - var(--bui-annotation-text-y));
  transform: translateX(-60%) rotate(var(--bui-annotation-rotate));
}

.bui-neat-annotation[data-direction="s"] > .bui-neat-annotation__arrow {
  left: calc(50% - 23px + var(--bui-annotation-arrow-x));
  top: calc(-1 * var(--bui-annotation-target-gap) - 35px + var(--bui-annotation-arrow-y));
  --bui-annotation-arrow-mask: url("data:image/svg+xml,%3Csvg width='46' height='38' viewBox='0 0 46 38' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M23 4 C22 13 22 24 23 35' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round'/%3E%3Cpath d='M17 29 L23 36 L29 29' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
}

.bui-neat-annotation[data-direction="s"] > .bui-neat-annotation__label {
  left: calc(50% + var(--bui-annotation-text-x));
  bottom: calc(100% + var(--bui-annotation-target-gap) + 31px + var(--bui-annotation-label-gap) - var(--bui-annotation-text-y));
  transform: translateX(-50%) rotate(var(--bui-annotation-rotate));
}

.bui-neat-annotation[data-direction="sw"] > .bui-neat-annotation__arrow {
  left: calc(50% - 6px + var(--bui-annotation-arrow-x));
  top: calc(-1 * var(--bui-annotation-target-gap) - 32px + var(--bui-annotation-arrow-y));
  transform: translateX(10%);
  --bui-annotation-arrow-mask: url("data:image/svg+xml,%3Csvg width='46' height='38' viewBox='0 0 46 38' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M40 6 C30 8 18 20 6 32' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round'/%3E%3Cpath d='M10 22 L6 32 L16 28' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
}

.bui-neat-annotation[data-direction="sw"] > .bui-neat-annotation__label {
  left: calc(50% + 34px + var(--bui-annotation-text-x));
  bottom: calc(100% + var(--bui-annotation-target-gap) + 26px + var(--bui-annotation-label-gap) - var(--bui-annotation-text-y));
  transform: translateX(-40%) rotate(var(--bui-annotation-rotate));
}

.bui-neat-annotation[data-direction="w"] > .bui-neat-annotation__arrow {
  left: calc(100% + var(--bui-annotation-target-gap) - 3px + var(--bui-annotation-arrow-x));
  top: calc(50% - 19px + var(--bui-annotation-arrow-y));
  --bui-annotation-arrow-mask: url("data:image/svg+xml,%3Csvg width='46' height='38' viewBox='0 0 46 38' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M43 19 C32 18 15 18 3 19' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round'/%3E%3Cpath d='M10 13 L3 19 L10 25' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
}

.bui-neat-annotation[data-direction="w"] > .bui-neat-annotation__label {
  left: calc(100% + var(--bui-annotation-target-gap) + 40px + var(--bui-annotation-label-gap) + var(--bui-annotation-text-x));
  top: calc(50% - 5px + var(--bui-annotation-text-y));
  transform: translateY(-50%) rotate(var(--bui-annotation-rotate));
}

.bui-neat-annotation[data-direction="nw"] > .bui-neat-annotation__arrow {
  left: calc(50% - 6px + var(--bui-annotation-arrow-x));
  top: calc(100% + var(--bui-annotation-target-gap) - 6px + var(--bui-annotation-arrow-y));
  transform: translateX(10%);
  --bui-annotation-arrow-mask: url("data:image/svg+xml,%3Csvg width='46' height='38' viewBox='0 0 46 38' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M40 32 C30 30 18 18 6 6' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round'/%3E%3Cpath d='M16 10 L6 6 L10 16' fill='none' stroke='black' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
}

.bui-neat-annotation[data-direction="nw"] > .bui-neat-annotation__label {
  left: calc(50% + 34px + var(--bui-annotation-text-x));
  top: calc(100% + var(--bui-annotation-target-gap) + 26px + var(--bui-annotation-lower-label-gap) + var(--bui-annotation-text-y));
  transform: translateX(-40%) rotate(var(--bui-annotation-rotate));
}

@property --bui-annotation-rainbow-hue {
  syntax: "<angle>";
  inherits: false;
  initial-value: 350deg;
}

@keyframes bui-neat-annotation-rainbow {
  to {
    --bui-annotation-rainbow-hue: 710deg;
  }
}

@media (prefers-reduced-motion: no-preference) {
  .bui-neat-annotation[data-tone="rainbow"] {
    animation: bui-neat-annotation-rainbow 3s linear infinite;
  }
}

@media (forced-colors: active) {
  .bui-neat-annotation {
    --bui-annotation-mark: transparent;
    outline: 1px solid CanvasText;
  }

  .bui-neat-annotation__arrow {
    background: CanvasText;
    forced-color-adjust: none;
  }

  .bui-neat-annotation__label {
    color: CanvasText;
    forced-color-adjust: none;
  }
}
`;

function useNeatAnnotationStyles() {
  useInsertionEffect(() => {
    if (typeof document === "undefined" || document.getElementById(STYLE_ID)) return;

    const element = document.createElement("style");
    element.id = STYLE_ID;
    element.textContent = STYLE_TEXT;
    document.head.appendChild(element);
  }, []);
}

export const NeatAnnotation = forwardRef<HTMLSpanElement, NeatAnnotationProps>(
  (
    {
      note,
      direction = "n",
      tone = "neutral",
      color,
      highlight = true,
      decorative = false,
      className,
      style,
      children,
      "aria-describedby": ariaDescribedBy,
      ...props
    },
    ref,
  ) => {
    useNeatAnnotationStyles();
    const generatedId = useId();
    const descriptionId = `bui-neat-annotation-${generatedId.replaceAll(":", "")}`;
    const hasNote = Boolean(note?.trim());
    const describedBy =
      hasNote && !decorative
        ? [ariaDescribedBy, descriptionId].filter(Boolean).join(" ")
        : ariaDescribedBy;
    const annotationStyle: NeatAnnotationStyle = {
      ...style,
      ...(color ? { "--bui-annotation-color": color } : {}),
    };

    return (
      <span
        {...props}
        ref={ref}
        className={["bui-neat-annotation", className].filter(Boolean).join(" ")}
        data-direction={direction}
        data-highlight={highlight ? "true" : "false"}
        data-tone={tone}
        aria-describedby={describedBy || undefined}
        style={annotationStyle}
      >
        {children}
        {hasNote ? (
          <>
            <span className="bui-neat-annotation__arrow" aria-hidden="true" />
            <span className="bui-neat-annotation__label" aria-hidden="true">
              {note}
            </span>
            {!decorative ? (
              <span id={descriptionId} className="bui-neat-annotation__description">
                {note}
              </span>
            ) : null}
          </>
        ) : null}
      </span>
    );
  },
);

NeatAnnotation.displayName = "NeatAnnotation";
